CREATE DATABASE IF NOT EXISTS ranjbar_maaref_v2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ranjbar_maaref_v2;
CREATE TABLE IF NOT EXISTS admin_users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,`role` ENUM('owner','content_manager','editor') NOT NULL DEFAULT 'owner',is_active TINYINT(1) NOT NULL DEFAULT 1,must_change_password TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,username_hash CHAR(64) NOT NULL,attempted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_admin_login_ip_time(ip_hash,attempted_at),INDEX idx_admin_login_user_time(ip_hash,username_hash,attempted_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS account_login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,username_hash CHAR(64) NOT NULL,attempted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_account_login_ip_time(ip_hash,attempted_at),INDEX idx_account_login_user_time(ip_hash,username_hash,attempted_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_admin_id INT UNSIGNED NULL,action VARCHAR(80) NOT NULL,target_type VARCHAR(80) NOT NULL,target_id BIGINT UNSIGNED NULL,details_json JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_admin_id) REFERENCES admin_users(id) ON DELETE SET NULL,INDEX(actor_admin_id,created_at),INDEX(target_type,target_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,slug VARCHAR(180) NOT NULL UNIQUE,kind ENUM('audio','article','announcement','collection','all') NOT NULL DEFAULT 'all',description TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS collections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT NULL,poster_url TEXT NULL,category_id INT UNSIGNED NULL,session_count INT UNSIGNED NULL,start_date_gregorian DATE NULL,end_date_gregorian DATE NULL,start_jalali VARCHAR(30) NULL,end_jalali VARCHAR(30) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,INDEX(category_id),INDEX idx_collection_dates(start_date_gregorian,end_date_gregorian)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lectures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,audio_url TEXT NOT NULL,category_id INT UNSIGNED NULL,session_date VARCHAR(100) NOT NULL,session_date_gregorian DATE NULL,hijri_date VARCHAR(100) NULL,description TEXT NULL,session_text LONGTEXT NULL,collection_id BIGINT UNSIGNED NULL,session_number INT NULL,session_count INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(collection_id) REFERENCES collections(id) ON DELETE SET NULL,INDEX(category_id),INDEX(created_at),INDEX idx_lecture_date(session_date_gregorian),INDEX(collection_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fishes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lecture_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NULL,body LONGTEXT NOT NULL,timestamp_seconds INT UNSIGNED NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(lecture_id) REFERENCES lectures(id) ON DELETE CASCADE,INDEX(lecture_id,timestamp_seconds)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS articles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,author VARCHAR(255) NULL,article_date VARCHAR(100) NULL,hijri_date VARCHAR(100) NULL,body LONGTEXT NOT NULL,category_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,INDEX(category_id),INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,body LONGTEXT NOT NULL,event_date VARCHAR(100) NULL,hijri_date VARCHAR(100) NULL,event_time VARCHAR(100) NULL,location VARCHAR(255) NULL,poster_url TEXT NULL,category_id INT UNSIGNED NULL,start_date_gregorian DATE NULL,end_date_gregorian DATE NULL,start_jalali VARCHAR(30) NULL,end_jalali VARCHAR(30) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,INDEX(category_id),INDEX(created_at),INDEX idx_announcement_dates(start_date_gregorian,end_date_gregorian)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS collection_lectures(collection_id BIGINT UNSIGNED NOT NULL,lecture_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(collection_id,lecture_id),FOREIGN KEY(collection_id) REFERENCES collections(id) ON DELETE CASCADE,FOREIGN KEY(lecture_id) REFERENCES lectures(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tags(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(191) NOT NULL UNIQUE,parent_id BIGINT UNSIGNED NULL,definition TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES tags(id) ON DELETE SET NULL,INDEX(parent_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tag_parents(tag_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(tag_id,parent_id),FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES tags(id) ON DELETE CASCADE,INDEX(parent_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS content_tags(content_type ENUM('lecture','fish','article','announcement','collection') NOT NULL,content_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(content_type,content_id,tag_id),FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE,INDEX(tag_id,content_type,content_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS internal_links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_fish_id BIGINT UNSIGNED NOT NULL,target_type ENUM('fish','article') NOT NULL,target_id BIGINT UNSIGNED NOT NULL,label VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_fish_id) REFERENCES fishes(id) ON DELETE CASCADE,INDEX(source_fish_id),INDEX(target_type,target_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS account_favorites(account_id BIGINT UNSIGNED NOT NULL,content_type ENUM('fish','lecture','article') NOT NULL,content_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(account_id,content_type,content_id),FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE,INDEX(content_type,content_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS account_lecture_progress(account_id BIGINT UNSIGNED NOT NULL,lecture_id BIGINT UNSIGNED NOT NULL,position_seconds INT UNSIGNED NOT NULL DEFAULT 0,duration_seconds INT UNSIGNED NOT NULL DEFAULT 0,is_completed TINYINT(1) NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(account_id,lecture_id),FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE,FOREIGN KEY(lecture_id) REFERENCES lectures(id) ON DELETE CASCADE,INDEX(updated_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lecture_photos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lecture_id BIGINT UNSIGNED NOT NULL,url TEXT NOT NULL,caption VARCHAR(255) NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(lecture_id) REFERENCES lectures(id) ON DELETE CASCADE,INDEX(lecture_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS site_settings(`key` VARCHAR(100) PRIMARY KEY,`value` TEXT NULL) ENGINE=InnoDB;
